          ..write('finePerDay: $finePerDay, ')
          ..write('graceDays: $graceDays, ')
          ..write('maximumFinePerCopy: $maximumFinePerCopy, ')
          ..write('maxOutstandingFine: $maxOutstandingFine, ')
          ..write('membershipDurationMonths: $membershipDurationMonths, ')
          ..write('reservationLimit: $reservationLimit, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

